<?php require_once 'config.php'; if(logged_in()) go_role(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=$conn->prepare('SELECT id,password,role FROM users WHERE email=? AND is_active=1');$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($pass,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_role']=$u['role'];go_role();}$error='Invalid login details.';} ?><!doctype html><html><head><meta charset="utf-8"><title>School Login</title><link rel="stylesheet" href="css/style.css"></head><body class="login"><form method="post" class="card"><h1>School Management</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Login</button></form></body></html>